import re
from collections import Counter

def word_count(text: str) -> dict[str, int]:
    # Keep only alphanumeric characters and Unicode letters for word building
    # Using regex to find all runs of Unicode letters (including accented ones) in lowercase
    words = re.findall(r'[a-zàáâãäåæçèéêëìíîïñòóôõöøùúûüýþß]', text, re.UNICODE)
    # Normalize: the pattern above already captures lowercase and accented chars directly if they exist in that set.
    # A more robust approach for "run of letters" including any accent is to match all letter sequences then lowercase.

    # Re-do with a proper Unicode letter match, then lowercase
    tokens = re.findall(r'\p{L}+', text)  # \p{L} matches any Unicode letter; Python's re doesn't support it natively without flags/regex_engine
    # Since stdlib re in Python doesn't support \p{L}, we use a different approach: keep letters via categories or transliterate.

    # Alternative: use regex with a set of known lowercase + accented chars is messy for all Unicode.
    # Best standard lib way: split on non-letter chars, then lowercase.

    import unicodedata

    def is_letter(c):
        return unicodedata.category(c).startswith('L')

    words = []
    current = []
    for ch in text.lower():
        if is_letter(ch):
            current.append(ch)
        else:
            if current:
                words.append("".join(current))
                current = []
    if current:
        words.append("".join(current))

    return dict(Counter(words))
