def _compare_identifiers(x: str, y: str) -> int:
    """Compare two pre-release identifiers according to SemVer rules."""
    x_num = int(x) if x.isdigit() else x
    y_num = int(y) if y.isdigit() else y

    # Numeric identifiers are less than alphanumeric ones
    if isinstance(x_num, int) and isinstance(y_num, str):
        return -1
    if isinstance(y_num, int) and isinstance(x_num, str):
        return 1

    # Both numeric: compare as numbers
    if isinstance(x_num, int) and isinstance(y_num, int):
        if x_num < y_num:
            return -1
        elif x_num > y_num:
            return 1
        return 0

    # Both alphanumeric: lexicographic comparison
    if x_num < y_num:
        return -1
    elif x_num > y_num:
        return 1
    return 0

def _compare_pre_releases(a_part: str, b_part: str) -> int:
    """Compare a single pre-release part."""
    return _compare_identifiers(a_part, b_part)

def compare_versions(a: str, b: str) -> int:
    """
    Compare Semantic Versioning 2.0.0 strings.

    Args:
        a: First version string (e.g., '1.2.3', '1.0.0-rc.1')
        b: Second version string (e.g., '1.2.3', '1.0.0-rc.1')

    Returns:
        -1 if a < b, 0 if a == b, 1 if a > b
    """
    def parse_version(v: str):
        # Split by dot, then separate build metadata after '+'
        parts = v.split('.')
        result = []
        for part in parts:
            if '+' in part:
                # Build metadata starts here; ignore it per spec
                main_part = part[:part.index('+')]
                result.append(main_part)
            elif '-' in part:
                pre_part = part[:part.index('-')]
                build_part = part[part.index('-')+1:]
                result.append(pre_part)
                # Build metadata is ignored, so we store a flag or empty string
                # Actually, per SemVer, if there's a build tag, it doesn't affect comparison.
                # But the split above might have merged pre and build incorrectly.
                # Let's restructure: split by dot first, then handle - and + within each segment.
                pass
            else:
                result.append(part)
        return result

    # Correct parsing approach
    a_tokens = []
    b_tokens = []

    for token in a.split('.'):
        if '+' in token:
            base, _ = token.split('+', 1)
            a_tokens.append(base)
        elif '-' in token:
            pre, _ = token.split('-', 1)
            a_tokens.append(pre)
        else:
            a_tokens.append(token)

    for token in b.split('.'):
        if '+' in token:
            base, _ = token.split('+', 1)
            b_tokens.append(base)
        elif '-' in token:
            pre, _ = token.split('-', 1)
            b_tokens.append(pre)
        else:
            b_tokens.append(token)

    # Compare top-level segments (patch, minor, major)
    for val_a, val_b in zip(a_tokens, b_tokens):
        if val_a != val_b:
            # Both are numeric or both alphanumeric; compare directly
            try:
                num_a = int(val_a)
                num_b = int(val_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            except ValueError:
                pass
            # Alphanumeric comparison
            if val_a < val_b:
                return -1
            elif val_a > val_b:
                return 1
            return 0

    # If lengths differ and all compared segments are equal, shorter is lower
    if len(a_tokens) < len(b_tokens):
        return -1
    elif len(a_tokens) > len(b_tokens):
        return 1

    # Now compare pre-release segments
    for i in range(len(a_tokens)):
        if a_tokens[i] != b_tokens[i]:
            # Compare identifier by identifier
            if a_tokens[i].isdigit() and b_tokens[i].isdigit():
                na = int(a_tokens[i])
                nb = int(b_tokens[i])
                if na < nb:
                    return -1
                elif na > nb:
                    return 1
            else:
                if a_tokens[i] < b_tokens[i]:
                    return -1
                elif a_tokens[i] > b_tokens[i]:
                    return 1

    return 0
