            vb = key_b[i]

            # Both are ints
            if isinstance(va, int) and isinstance(vb, int):
                if va < vb:
                    return -1
                elif va > vb:
                    return 1
            # Both are chars (strings of length 1)
            elif isinstance(va, str) and isinstance(vb, str):
                if va < vb:
                    return -1
                elif va > vb:
                    return 1
            # Mixed case: int vs str -> numbers come before letters? 
            # Actually, in natural sort, we treat the converted list uniformly.
            # But our convert alternates types. To make comparison work with cmp_to_key,
            # we need a consistent type. Let's re-convert to uniform types.
        return len(key_a) - len(key_b)

    # Redefine key for stable sort with custom comparator logic embedded
    def sort_key(name: str):
        parts = convert(name)
        res = []
        for p in parts:
            if isinstance(p, int):
                res.append((0, p))
            else:
                res.append((1, p))
        return tuple(res)

    # However, cmp_to_key requires a comparator function. 
    # Let's use the key approach with a transformed tuple that supports ordering.
    # Since cmp_to_key handles comparisons between keys generated by a function,
    # and Python 3 doesn't support mixed-type tuple comparison well without custom logic,
    # we'll construct a comparable key where numbers are ints and letters are strings,
    # but we must handle the alternating types carefully.

    # Alternative: use a list as key? No, lists can't be compared with mixed types in all cases?
    # Actually, tuples of mixed int/str are allowed in Python and compare element-wise.
    # But int < str raises TypeError in some versions or compares by type? 
    # In Python 3, comparing int and str raises TypeError. So we must unify.

    # Unified approach:
    # Represent each part as (type_tag, value). type_tag 0 for int, 1 for str.
    # Then compare tuples. Since we converted everything to either int or string (single char),
    # and the original loop appends ints and single-char strings alternately? 
    # Actually, convert returns a list where digits are collected into one int, then a non-digit char is appended.
    # So the result is alternating: int, str, int, str... or just all ints or all strs.

    def natural_key(name):
        parts = convert(name)
        key = []
        for p in parts:
            if isinstance(p, int):
                key.append((0, p))
            else:
                key.append((1, p))
        return key

    # But (0, 2) < (1, 'f')? Yes, because 0 < 1. That means numbers always come before letters 
    # in the same position. Is that correct? In "file2" vs "filea", at pos 4: '2' (int) vs 'a' (str).
    # Our key makes (0, 2) < (1, 'a'), so "file2" < "filea". That is generally acceptable in natural sort.
    # Also case-insensitive: we converted to lower().

    return sorted(names, key=natural_key)
