def deep_merge(base: dict, override: dict) -> dict:
    """
    Returns a new dict where keys from `override` take precedence over `base`.
    Nested dicts are merged recursively; lists and other values are replaced.
    An override value of None deletes the key from the result.
    Neither input is modified, and the result does not share nested structures.
    """
    result: dict = {}

    # Determine all keys present in either dictionary
    all_keys = set(base.keys()) | set(override.keys())

    for key in all_keys:
        base_val = base.get(key)
        override_val = override.get(key)

        if key in override and override_val is not None:
            if isinstance(base_val, dict) and isinstance(override_val, dict):
                # Recursive merge for nested dicts
                result[key] = deep_merge(base_val, override_val)
            elif isinstance(base_val, list) and isinstance(override_val, list):
                # Lists are replaced (per spec: lists and other values are replaced)
                result[key] = override_val
            else:
                # Override wins directly
                result[key] = override_val
        else:
            # Key only in base or value is None (deleted)
            if base_val is not None:
                result[key] = base_val

    return result
