from datetime import datetime, timezone
from typing import List, Dict, Any

def latest_by_key(records: List[Dict[str, Any]], key: str) -> List[Dict[str, Any]]:
    """
    Keeps one record per value of record[key]: the one with the latest 'updated_at'.
    updated_at is an ISO 8601 string that may use different UTC offsets.
    On a tie, keeps the record that comes later in the list.
    Returns records ordered by the first appearance of each key's value.

    Args:
        records: List of dictionaries, each containing 'key' and 'updated_at'.
        key: The field name used to group records.

    Returns:
        A list of selected records ordered by the first occurrence of each key value.
    """
    if not records:
        return []

    # Map from key_value -> (datetime_utc, index_in_list)
    best: Dict[Any, tuple] = {}

    for idx, rec in enumerate(records):
        k_val = rec.get(key)
        if k_val is None:
            continue  # skip records without the key field
        dt_str = rec.get("updated_at")
        if not dt_str:
            continue

        # Parse ISO 8601 with possible offset/Z
        try:
            dt = datetime.fromisoformat(dt_str)
            # fromisoformat handles Z as UTC in Python 3.11+, but to be safe across versions:
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            else:
                # Ensure timezone is aware
                if dt.tzinfo is not None and str(dt.tzinfo).startswith('UTC'):
                    pass  # keep as is
                elif dt.tzinfo is not None:
                    # fromisoformat already creates an aware datetime with the offset
                    pass
        except ValueError:
            continue  # skip unparseable timestamps

        if k_val not in best:
            best[k_val] = (dt, idx)
        else:
            existing_dt, existing_idx = best[k_val]
            if dt > existing_dt or (dt == existing_dt and idx > existing_idx):
                best[k_val] = (dt, idx)

    # Determine order of first appearance
    seen_order: List[Any] = []
    for rec in records:
        k_val = rec.get(key)
        if k_val is not None and k_val not in seen_order:
            seen_order.append(k_val)

    result = [best[k_val] for k_val in seen_order if k_val in best]
    return [rec for dt, idx in result for rec in records[idx]]
