import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    """
    Tells whether ip is inside any of the CIDR networks (IPv4 or IPv6).

    Args:
        ip (str): The IP address to check.
        networks (list[str]): A list of CIDR network strings.

    Returns:
        bool: True if the IP is inside any of the networks, False otherwise.

    Raises:
        ValueError: If a network string is invalid.
    """
    try:
        # Validate each network first; raise on invalid network
        addr_obj = ipaddress.ip_address(ip)
        for net_str in networks:
            net = ipaddress.ip_network(net_str, strict=False)
            if isinstance(addr_obj, ipaddress.IPv4Address):
                # Check raw IPv4 address against all networks
                # IPv6-mapped IPv4 addresses (like ::ffff:x.x.x.x) need special handling
                is_in_network = False
                for n in net:
                    if isinstance(n, ipaddress.IPv4Network):
                        if addr_obj in n:
                            is_in_network = True
                            break
                    elif isinstance(n, ipaddress.IPv6Network):
                        # Check the embedded IPv4 part of the IPv6 network
                        v4_net = n.ipv4_network()
                        if addr_obj in v4_net:
                            is_in_network = True
                            break
                if is_in_network:
                    return True
            else:
                # IPv6 address: direct check, plus check for embedded IPv4
                is_in_network = False
                for n in net:
                    if isinstance(n, ipaddress.IPv6Network):
                        if addr_obj in n:
                            is_in_network = True
                            break
                    elif isinstance(n, ipaddress.IPv4Network):
                        # For IPv4 networks, check the raw IPv4 address
                        if addr_obj in n:
                            is_in_network = True
                            break
                if is_in_network:
                    return True

        return False

    except (ValueError, TypeError):
        # Invalid IP address or unexpected type
        return False
