def is_not_prime(n: int) -> bool:
    """
    Returns True if n is not prime, False otherwise.
    Only positive integers are considered; 0 and 1 are non-prime.
    """
    if n < 2:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True
    i = 3
    while i * i <= n:
        if n % i == 0:
            return True
        i += 2
    return False
