from datetime import date, timedelta
from typing import Set

def add_business_days(d: date, n: int, holidays: Set[date]) -> date:
    """
    Moves n business days (Monday to Friday, not in holidays) from d.
    n may be negative. d itself never counts as one of the n days.
    With n == 0, returns d if it is a business day, otherwise the next business day.
    """
    def is_business_day(date_obj: date) -> bool:
        return date_obj.weekday() < 5 and date_obj not in holidays

    if n == 0:
        if is_business_day(d):
            return d
        # find next business day
        tomorrow = d + timedelta(days=1)
        while not is_business_day(tomorrow):
            tomorrow += timedelta(days=1)
        return tomorrow

    # direction: positive n -> forward, negative n -> backward
    step = timedelta(days=1)
    if n > 0:
        candidate = d + step
    else:
        candidate = d - step * (-1)  # i.e., d - step

    count = 0
    while count < abs(n):
        if is_business_day(candidate):
            count += 1
        if count == abs(n):
            break
        if n > 0:
            candidate += step
        else:
            candidate -= step
    return candidate
