        accent_count = sum(1 for c in name if c.lower() in accent_set)
        # To make "no accents first", we want a smaller key for fewer accents.
        # So tuple: (no_acc_no_case, accent_count, original_string)
        return (no_acc_no_case, accent_count, name)

    names.sort(key=key_func)
    return names
