def is_not_prime(n: int) -> bool:
    """Return True if n is not a prime number, False otherwise."""
    if n < 2:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True
    i = 3
    while i * i <= n:
        if n % i == 0:
            return True
        i += 2
    return False
